//! The macro events calendar (design:
//! `docs/superpowers/specs/2026-11-06-macro-events-design.md`): FOMC
//! decisions and minutes, the BLS jobs report and CPI, US federal elections
//! and market closures, shown beside earnings and in the premarket brief's
//! "What to watch".
//!
//! Dates come from `data/events.tsv` (generated by `scripts/build-events.mjs`
//! from the official schedules) and, for closures, from `clock`. A daily
//! check (`check`) loads them into D1, re-reads the official pages for
//! moved or postponed dates and marks releases once their page is up.
//! Titles come from the glossary here, never from a row or an LLM.

pub mod check;
pub mod parse;
pub mod store;
pub mod watch;

use std::sync::OnceLock;

use chrono::{DateTime, Datelike, Duration, NaiveDate, Utc};

use crate::clock::{trading_day, DayKind};
use crate::numbers::Lang;

const DATA: &str = include_str!("../../data/events.tsv");

/// The NYSE page that lists its holidays and early closes, the proof for
/// the closures written from `clock`'s table.
pub const NYSE_HOURS_URL: &str = "https://www.nyse.com/markets/hours-calendars";

/// Tier 1: major (FOMC decisions, jobs, CPI, elections); 2: notable
/// (minutes, closures); 3: minor (none in v1). The page and the brief filter
/// by tier, not by kind.
pub const TIER_MAJOR: u8 = 1;
pub const TIER_NOTABLE: u8 = 2;

/// An event as the official schedule (or `clock`) gives it.
#[derive(Debug, Clone, PartialEq)]
pub struct Planned {
    /// `source:series:period`, e.g. `bls:cpi:2026-10`; stays when the date moves.
    pub id: String,
    pub series: String,
    /// `YYYY-MM` for a monthly release or an FOMC meeting's month,
    /// `YYYY-MM-DD` (the meeting's last day) for minutes, `None` otherwise.
    pub ref_period: Option<String>,
    /// `sep` (an FOMC meeting with projections), `midterm` / `general`
    /// (elections), else `None`.
    pub variant: Option<String>,
    /// `None` for all-day events (elections, closures).
    pub starts_at: Option<DateTime<Utc>>,
    /// The ET calendar day it shows on.
    pub et_date: NaiveDate,
    pub tier: u8,
    /// The official page that lists the date.
    pub proof_url: String,
}

fn opt(s: &str) -> Option<String> {
    (!s.is_empty() && s != "-").then(|| s.to_string())
}

fn parse_line(line: &str) -> Option<Planned> {
    let c: Vec<&str> = line.split('\t').map(str::trim).collect();
    let [id, series, ref_period, variant, starts_at, et_date, tier, proof_url] = c[..] else {
        return None;
    };
    let starts_at = match opt(starts_at) {
        Some(t) => Some(t.parse::<DateTime<Utc>>().ok()?),
        None => None,
    };
    Some(Planned {
        id: id.into(),
        series: series.into(),
        ref_period: opt(ref_period),
        variant: opt(variant),
        starts_at,
        et_date: et_date.parse().ok()?,
        tier: tier.parse().ok()?,
        proof_url: proof_url.into(),
    })
}

fn data_lines() -> impl Iterator<Item = &'static str> {
    DATA.lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
}

/// Every row of `data/events.tsv`, in file order (by date).
pub fn snapshot() -> &'static [Planned] {
    static S: OnceLock<Vec<Planned>> = OnceLock::new();
    S.get_or_init(|| data_lines().filter_map(parse_line).collect())
}

/// The snapshot's official-schedule window, from its `# covers:` line.
pub fn snapshot_covers() -> Option<(NaiveDate, NaiveDate)> {
    let line = DATA.lines().find_map(|l| l.strip_prefix("# covers:"))?;
    let mut it = line.split_whitespace().map(|d| d.parse().ok());
    Some((it.next()??, it.next()??))
}

/// Market closures and early closes on weekdays from `from` to `to`, from
/// `clock`'s NYSE table (2026-2027; other years have none).
pub fn closures(from: NaiveDate, to: NaiveDate) -> Vec<Planned> {
    let mut out = Vec::new();
    let mut d = from;
    while d <= to {
        let weekday = d.weekday().number_from_monday() <= 5;
        let series = match trading_day(d) {
            DayKind::Closed if weekday => Some("closed"),
            DayKind::EarlyClose => Some("early_close"),
            _ => None,
        };
        if let Some(series) = series {
            out.push(Planned {
                id: format!("nyse:{series}:{d}"),
                series: series.into(),
                ref_period: None,
                variant: None,
                starts_at: None,
                et_date: d,
                tier: TIER_NOTABLE,
                proof_url: NYSE_HOURS_URL.into(),
            });
        }
        d += Duration::days(1);
    }
    out
}

/// The snapshot and the closures with `from <= et_date <= to`, by date.
pub fn planned(from: NaiveDate, to: NaiveDate) -> Vec<Planned> {
    let mut out: Vec<Planned> = snapshot()
        .iter()
        .filter(|p| p.et_date >= from && p.et_date <= to)
        .cloned()
        .chain(closures(from, to))
        .collect();
    out.sort_by(|a, b| (a.et_date, a.starts_at, &a.id).cmp(&(b.et_date, b.starts_at, &b.id)));
    out
}

/// Whether a snapshot event started within the last `minutes` of `now`:
/// its release may be out and is worth one check.
pub fn release_due(now: DateTime<Utc>, minutes: i64) -> bool {
    snapshot().iter().any(|p| {
        p.starts_at
            .is_some_and(|t| t <= now && now - t < Duration::minutes(minutes))
            && release_url_for(&p.series, p.et_date, p.ref_period.as_deref()).is_some()
    })
}

/// Where the release itself will be once it is out, from the agencies'
/// fixed URL patterns: `None` for kinds without one (elections, closures).
pub fn release_url_for(
    series: &str,
    et_date: NaiveDate,
    ref_period: Option<&str>,
) -> Option<String> {
    let mdy = et_date.format("%m%d%Y");
    match series {
        "jobs" => Some(format!(
            "https://www.bls.gov/news.release/archives/empsit_{mdy}.htm"
        )),
        "cpi" => Some(format!(
            "https://www.bls.gov/news.release/archives/cpi_{mdy}.htm"
        )),
        "fomc" => Some(format!(
            "https://www.federalreserve.gov/newsevents/pressreleases/monetary{}a.htm",
            et_date.format("%Y%m%d")
        )),
        "fomc_minutes" => {
            let meeting: NaiveDate = ref_period?.parse().ok()?;
            Some(format!(
                "https://www.federalreserve.gov/monetarypolicy/fomcminutes{}.htm",
                meeting.format("%Y%m%d")
            ))
        }
        _ => None,
    }
}

// ---------------------------------------------------------------------------
// Glossary. The web keeps the same strings in `apps/web/src/lib/events.ts`
// (a test below checks it), so a title reads the same on the page and in
// the brief.

/// `(key, EN, ZH)`. `{month}` is the English month name, `{m}` its number.
/// Elections key on their variant (`election:midterm`).
pub const GLOSSARY: &[(&str, &str, &str)] = &[
    (
        "fomc",
        "FOMC rate decision",
        "联邦公开市场委员会（FOMC）议息会议",
    ),
    (
        "fomc_minutes",
        "FOMC minutes ({month} meeting)",
        "FOMC会议纪要（{m}月会议）",
    ),
    ("jobs", "{month} jobs report", "{m}月非农就业报告"),
    ("cpi", "{month} CPI", "{m}月消费者物价指数（CPI）"),
    ("election:midterm", "US midterm elections", "美国中期选举"),
    ("election:general", "US general election", "美国大选"),
    ("closed", "US stock market closed", "美股休市"),
    (
        "early_close",
        "Early close, 1:00 PM ET",
        "美股提前收盘（美东13:00）",
    ),
];

/// Added to an FOMC decision with projections.
pub const SEP_SUFFIX: (&str, &str) = (" (with projections)", "（含经济预测）");
/// Shown under an FOMC decision: every meeting has a press conference.
pub const FOMC_NOTE: (&str, &str) = (
    "Press conference 2:30 PM ET",
    "美联储主席新闻发布会，美东14:30",
);

const MONTH_NAMES: [&str; 12] = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
];

fn pick(pair: (&'static str, &'static str), lang: Lang) -> &'static str {
    match lang {
        Lang::En => pair.0,
        Lang::Zh => pair.1,
    }
}

/// The event's title in `lang`, or `None` for a series the glossary lacks
/// (such rows are not shown).
pub fn title(
    series: &str,
    ref_period: Option<&str>,
    variant: Option<&str>,
    lang: Lang,
) -> Option<String> {
    let key = match (series, variant) {
        ("election", Some(v)) => format!("election:{v}"),
        _ => series.to_string(),
    };
    let (_, en, zh) = GLOSSARY.iter().find(|(k, _, _)| *k == key)?;
    let mut t = pick((en, zh), lang).to_string();
    if t.contains("{month}") || t.contains("{m}") {
        let month: u32 = ref_period?.get(5..7)?.parse().ok()?;
        let name = MONTH_NAMES.get(usize::try_from(month).ok()?.checked_sub(1)?)?;
        t = t
            .replace("{month}", name)
            .replace("{m}", &month.to_string());
    }
    if series == "fomc" && variant == Some("sep") {
        t.push_str(pick(SEP_SUFFIX, lang));
    }
    Some(t)
}

/// The line shown under the title, if any (the FOMC press conference).
pub fn note(series: &str, lang: Lang) -> Option<&'static str> {
    (series == "fomc").then(|| pick(FOMC_NOTE, lang))
}

/// An ET clock time as the brief and the page write it: "8:30 AM ET" /
/// "美东 8:30", "2:00 PM ET" / "美东 14:00".
pub fn et_time(t: DateTime<Utc>, lang: Lang) -> String {
    let local = crate::clock::et(t);
    match lang {
        Lang::En => format!("{} ET", local.format("%-I:%M %p")),
        Lang::Zh => format!("美东 {}", local.format("%-H:%M")),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn d(s: &str) -> NaiveDate {
        s.parse().unwrap()
    }
    fn utc(s: &str) -> DateTime<Utc> {
        s.parse().unwrap()
    }

    #[test]
    fn every_snapshot_row_parses_with_a_title_and_official_proof() {
        let n = data_lines().count();
        assert_eq!(snapshot().len(), n, "a row of events.tsv does not parse");
        assert!(n >= 30, "{n} rows");
        let mut ids = std::collections::HashSet::new();
        for p in snapshot() {
            assert!(ids.insert(&p.id), "duplicate id {}", p.id);
            assert!(p.proof_url.starts_with("https://www."), "{}", p.id);
            for lang in [Lang::En, Lang::Zh] {
                assert!(
                    title(
                        &p.series,
                        p.ref_period.as_deref(),
                        p.variant.as_deref(),
                        lang
                    )
                    .is_some(),
                    "no title for {}",
                    p.id
                );
            }
            assert!([TIER_MAJOR, TIER_NOTABLE].contains(&p.tier), "{}", p.id);
            // Timed events start on their ET day.
            if let Some(t) = p.starts_at {
                assert_eq!(crate::clock::et(t).date_naive(), p.et_date, "{}", p.id);
            }
        }
    }

    #[test]
    fn snapshot_has_the_v1_kinds_and_only_them() {
        let series: std::collections::BTreeSet<&str> =
            snapshot().iter().map(|p| p.series.as_str()).collect();
        assert_eq!(
            series.into_iter().collect::<Vec<_>>(),
            ["cpi", "election", "fomc", "fomc_minutes", "jobs"]
        );
        let cpi = snapshot()
            .iter()
            .find(|p| p.id == "bls:cpi:2026-10")
            .unwrap();
        assert_eq!(cpi.et_date, d("2026-11-10"));
        assert_eq!(cpi.starts_at, Some(utc("2026-11-10T13:30:00Z")));
        let fomc = snapshot()
            .iter()
            .find(|p| p.id == "fed:fomc:2026-12")
            .unwrap();
        assert_eq!(fomc.variant.as_deref(), Some("sep"));
        assert_eq!(fomc.starts_at, Some(utc("2026-12-09T19:00:00Z")));
        let e = snapshot()
            .iter()
            .find(|p| p.id == "us:election:2028-11-07")
            .unwrap();
        assert_eq!((e.starts_at, e.variant.as_deref()), (None, Some("general")));
        let (from, to) = snapshot_covers().unwrap();
        assert!(from < d("2026-11-06") && to > d("2027-06-01"));
    }

    #[test]
    fn closures_come_from_the_clock_table() {
        let c = closures(d("2026-11-23"), d("2026-12-31"));
        let ids: Vec<&str> = c.iter().map(|p| p.id.as_str()).collect();
        assert_eq!(
            ids,
            [
                "nyse:closed:2026-11-26",
                "nyse:early_close:2026-11-27",
                "nyse:early_close:2026-12-24",
                "nyse:closed:2026-12-25",
            ]
        );
        assert!(c
            .iter()
            .all(|p| p.tier == TIER_NOTABLE && p.starts_at.is_none()));
        // Weekends are not closures.
        assert!(closures(d("2026-11-07"), d("2026-11-08")).is_empty());
    }

    #[test]
    fn planned_merges_snapshot_and_closures_by_date() {
        let p = planned(d("2026-11-23"), d("2026-11-30"));
        let ids: Vec<&str> = p.iter().map(|p| p.id.as_str()).collect();
        assert_eq!(
            ids,
            ["nyse:closed:2026-11-26", "nyse:early_close:2026-11-27"]
        );
        let p = planned(d("2026-12-07"), d("2026-12-11"));
        let ids: Vec<&str> = p.iter().map(|p| p.id.as_str()).collect();
        assert_eq!(ids, ["fed:fomc:2026-12", "bls:cpi:2026-11"]);
    }

    #[test]
    fn titles_from_the_glossary() {
        let t = |s, r, v, l| title(s, r, v, l).unwrap();
        assert_eq!(t("cpi", Some("2026-10"), None, Lang::En), "October CPI");
        assert_eq!(
            t("cpi", Some("2026-10"), None, Lang::Zh),
            "10月消费者物价指数（CPI）"
        );
        assert_eq!(
            t("jobs", Some("2026-11"), None, Lang::En),
            "November jobs report"
        );
        assert_eq!(
            t("jobs", Some("2026-11"), None, Lang::Zh),
            "11月非农就业报告"
        );
        assert_eq!(
            t("fomc", Some("2026-12"), Some("sep"), Lang::En),
            "FOMC rate decision (with projections)"
        );
        assert_eq!(
            t("fomc", Some("2027-01"), None, Lang::Zh),
            "联邦公开市场委员会（FOMC）议息会议"
        );
        assert_eq!(
            t("fomc_minutes", Some("2026-10-28"), None, Lang::En),
            "FOMC minutes (October meeting)"
        );
        assert_eq!(
            t("election", None, Some("midterm"), Lang::Zh),
            "美国中期选举"
        );
        assert_eq!(
            t("election", None, Some("general"), Lang::En),
            "US general election"
        );
        assert_eq!(title("ppi", Some("2026-10"), None, Lang::En), None);
        assert_eq!(title("cpi", None, None, Lang::En), None);
        assert_eq!(note("fomc", Lang::En), Some("Press conference 2:30 PM ET"));
        assert_eq!(note("cpi", Lang::En), None);
    }

    #[test]
    fn et_times_in_both_languages_and_offsets() {
        assert_eq!(et_time(utc("2026-11-10T13:30:00Z"), Lang::En), "8:30 AM ET");
        assert_eq!(et_time(utc("2026-11-10T13:30:00Z"), Lang::Zh), "美东 8:30");
        assert_eq!(et_time(utc("2026-10-28T18:00:00Z"), Lang::En), "2:00 PM ET");
        assert_eq!(et_time(utc("2026-10-28T18:00:00Z"), Lang::Zh), "美东 14:00");
    }

    #[test]
    fn release_urls_follow_the_agency_patterns() {
        assert_eq!(
            release_url_for("jobs", d("2026-11-06"), Some("2026-10")).unwrap(),
            "https://www.bls.gov/news.release/archives/empsit_11062026.htm"
        );
        assert_eq!(
            release_url_for("cpi", d("2026-10-14"), Some("2026-09")).unwrap(),
            "https://www.bls.gov/news.release/archives/cpi_10142026.htm"
        );
        assert_eq!(
            release_url_for("fomc", d("2026-10-28"), Some("2026-10")).unwrap(),
            "https://www.federalreserve.gov/newsevents/pressreleases/monetary20261028a.htm"
        );
        assert_eq!(
            release_url_for("fomc_minutes", d("2026-11-18"), Some("2026-10-28")).unwrap(),
            "https://www.federalreserve.gov/monetarypolicy/fomcminutes20261028.htm"
        );
        assert_eq!(release_url_for("election", d("2028-11-07"), None), None);
    }

    #[test]
    fn a_release_is_due_just_after_its_time() {
        assert!(release_due(utc("2026-11-10T13:31:00Z"), 120));
        assert!(!release_due(utc("2026-11-10T13:29:00Z"), 120));
        assert!(!release_due(utc("2026-11-10T16:00:00Z"), 120));
    }
}
